import React,{useEffect,useState} from 'react';
import './styles.css';
const API=(import.meta.env.VITE_API_URL||'https://mic2-api.onrender.com').replace(/\/$/,'');
const NAV=[['overview','⌂','Обзор'],['schedule','▦','Расписание'],['cycles','◉','Производственные циклы'],['qc-my-shifts','▦','Мои смены'],['qc-production','▣','Производство сейчас'],['qc-fly','⌁','Летучий контроль'],['qc','✓','Очередь ОТК'],['qc-history','◷','История проверок'],['qc-cards','▤','Карты измерений'],['qc-defects','⚑','Решения по дефектам'],['bins','▤','Контейнеры'],['products','◇','Изделия и наладки'],['admin','⚙','Управление доступами'],['qc-calendar','▦','Календарь смен']];
const ROLE_PAGES={administrator:['overview','schedule','cycles','qc-my-shifts','qc-production','qc-fly','qc','qc-history','qc-cards','qc-defects','bins','products','admin'],production_manager:['overview','schedule','cycles','bins','products'],cnc_operator:['cycles'],qc_controller:['qc-production','qc-fly','qc','qc-history','qc-calendar'],qc_manager:['overview','schedule','qc-production','qc-fly','qc','qc-history','qc-cards','qc-defects'],technical_director:['overview','products']};
const HOME_PAGE={administrator:'overview',production_manager:'overview',cnc_operator:'cycles',qc_controller:'qc-calendar',qc_manager:'overview',technical_director:'overview'};
const TITLES={'qc-my-shifts':'Мои смены','qc-calendar':'Календарь смен','qc-production':'Производство сейчас','qc-fly':'Летучий контроль',overview:'Панель управления',schedule:'Расписание смен',cycles:'Производственные циклы',qc:'Очередь контроля ОТК','qc-history':'История проверок ОТК','qc-cards':'Карты измерений','qc-defects':'Решения по дефектам',bins:'Пластиковые контейнеры',products:'Изделия и наладки',admin:'Управление доступами'};
const ROLES=[['cnc_operator','Оператор ЧПУ'],['qc_controller','Контролёр ОТК'],['production_manager','Начальник производства'],['qc_manager','Начальник ОТК'],['technical_director','Технический директор'],['administrator','Администратор']];
export default function App(){
 const [token,setToken]=useState(localStorage.getItem('mic2_token')||''),[employee,setEmployee]=useState(null),[login,setLogin]=useState('admin'),[password,setPassword]=useState(''),[page,setPage]=useState('overview'),[data,setData]=useState({}),[error,setError]=useState(''),[busy,setBusy]=useState(false),[modal,setModal]=useState(''),[form,setForm]=useState({}),[lookups,setLookups]=useState({});
 async function req(path,opts={}){const r=await fetch(API+path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(opts.headers||{})}});const j=await r.json().catch(()=>({message:'Ошибка ответа сервера'}));if(!r.ok)throw Error(j.message||'Ошибка запроса');return j;}
 async function load(){setBusy(true);setError('');try{const d=await req(({admin:'/api/admin/accounts',overview:'/api/dashboard',schedule:'/api/production/shifts','qc-my-shifts':'/api/qc/my-shifts','qc-calendar':'/api/qc/calendar','qc-production':'/api/qc/production','qc-fly':'/api/qc/fly-control',cycles:'/api/cycles',qc:'/api/qc/pending','qc-history':'/api/qc/history','qc-cards':'/api/qc/cards','qc-defects':'/api/qc/defects',bins:'/api/bins',products:'/api/products'})[page]);setData(d);if(d.employee)setEmployee(d.employee);}catch(e){setError(e.message);if(/авторизац|сессия|токен/i.test(e.message)){localStorage.removeItem('mic2_token');setToken('');}}finally{setBusy(false);}}
 useEffect(()=>{if(!token)return;req('/api/auth/me').then(r=>{setEmployee(r.employee);setPage(current=>ROLE_PAGES[r.employee.role_code]?.includes(current)?current:(HOME_PAGE[r.employee.role_code]||'overview'));}).catch(()=>{localStorage.removeItem('mic2_token');setToken('');setEmployee(null);});},[token]);
 useEffect(()=>{if(token&&employee&&ROLE_PAGES[employee.role_code]?.includes(page))load();},[token,page,employee]);
 async function signIn(e){e.preventDefault();setError('');setBusy(true);try{const r=await fetch(API+'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login,password})});const j=await r.json();if(!r.ok)throw Error(j.message||'Не удалось войти');localStorage.setItem('mic2_token',j.token);setEmployee(j.employee);setPage(HOME_PAGE[j.employee.role_code]||'overview');setToken(j.token);}catch(e){setError(e.message);}finally{setBusy(false);}}
 function logout(){localStorage.removeItem('mic2_token');setToken('');setEmployee(null);setPassword('');}
 function set(k,v){setForm(f=>({...f,[k]:v}));}
 function setMeasurement(index,key,value){setForm(f=>({...f,measurements:(f.measurements||[]).map((m,i)=>i===index?{...m,[key]:value}:m)}));}
 function setFlyMeasurement(parameterId,value){setForm(f=>({...f,measurements:(f.measurements||[]).map(m=>m.parameter_id===parameterId?{...m,measured_value:value}:m)}));}
 function addCardParameter(){setForm(f=>({...f,parameters:[...(f.parameters||[]),{parameter_name:'',nominal_value:'',tolerance_text:'',unit:'',instruction:''}]}));}
 function setCardParameter(index,key,value){setForm(f=>({...f,parameters:(f.parameters||[]).map((p,i)=>i===index?{...p,[key]:value}:p)}));}
 async function openCreate(kind,selectedDate){setError('');setForm(kind==='shift'?{shift_date:selectedDate||new Date().toLocaleDateString('en-CA'),shift_code:'day'}:kind==='shiftPattern'?{start_date:selectedDate||new Date().toLocaleDateString('en-CA'),pattern_code:'5x2'}:{});setModal(kind);if(kind==='cycle'){try{const [b,p,o]=await Promise.all([req('/api/bins'),req('/api/products'),req('/api/production/operators')]);setLookups({bins:b.bins.filter(x=>x.bin_status==='free'),products:p.products,operators:o.operators});}catch(err){setError(err.message);setModal('');}}if(kind==='shift'||kind==='shiftPattern'){try{const r=await req('/api/production/shift-candidates');setLookups({candidates:r.candidates});setForm(f=>({...f,employee_id:f.employee_id||String(r.candidates?.[0]?.id||'')}));}catch(err){setError(err.message);setModal('');}}if(kind==='card'){try{const r=await req('/api/products');setLookups({products:r.products});setForm({parameters:[{parameter_name:'',nominal_value:'',tolerance_text:'',unit:'',instruction:''}]});}catch(err){setError(err.message);setModal('');}}}
 async function submit(e){e.preventDefault();setBusy(true);setError('');try{
  let path='',body={...form};
  if(modal==='bin')path='/api/bins';
  if(modal==='product')path='/api/products';
  if(modal==='employee')path='/api/admin/accounts';
  if(modal==='shift'){path='/api/production/shifts';body={employee_id:Number(form.employee_id),shift_date:form.shift_date,shift_code:form.shift_code,notes:form.notes||''};}
  if(modal==='shiftPattern'){path='/api/production/shift-patterns';body={employee_id:Number(form.employee_id),pattern_code:form.pattern_code,start_date:form.start_date,notes:form.notes||''};}
  if(modal==='cycle')path='/api/cycles';
  if(modal==='output'){path='/api/cycles/'+form.cycle_id+'/output';body={quantity:Number(form.quantity),note:form.note||''};}
  if(modal==='qc'){path='/api/qc/inspect';body={cycle_id:Number(form.cycle_id),good_quantity:Number(form.good_quantity),defect_quantity:Number(form.defect_quantity),defect_description:form.defect_description||'',comment:form.comment||'',measurements:form.measurements||[]};}
  if(modal==='card'){path='/api/qc/cards';body={setup_id:Number(form.setup_id),parameters:form.parameters||[]};}
  if(modal==='fly'){path='/api/qc/fly-control';body={...form,cycle_id:Number(form.cycle_id),sample_quantity:Number(form.sample_quantity),defect_quantity:Number(form.defect_quantity||0),measurements:form.measurements||[]};}
  await req(path,{method:'POST',body:JSON.stringify(body)});setModal('');setForm({});await load();
 }catch(err){setError(err.message);}finally{setBusy(false);}}
 if(!token)return <div className="login"><form className="loginCard" onSubmit={signIn}><div className="brand"><b className="mark">M</b><span><strong>MIC 2.0</strong><small>PRODUCTION INTELLIGENCE</small></span></div><div className="eyebrow">ЕДИНАЯ ПРОИЗВОДСТВЕННАЯ СИСТЕМА</div><h1>Добро пожаловать</h1><p>Войдите, чтобы управлять производством, контейнерами и контролем качества.</p><label>Логин<input value={login} onChange={e=>setLogin(e.target.value)} autoComplete="username" required/></label><label>Пароль<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></label><button className="primary" disabled={busy}>{busy?'Входим…':'Войти в MIC 2.0'}</button>{error&&<div className="error">{error}</div>}</form></div>;
 const metrics=data.metrics||{};
 const allowedPages=ROLE_PAGES[employee?.role_code]||[];
 const visibleNav=NAV.filter(([id])=>allowedPages.includes(id));
 if(!allowedPages.includes(page)){if(allowedPages.length)setPage(allowedPages[0]);return <div className="loading">Открываем доступный раздел…</div>;}
 const actionLabel={cycles:'Открыть цикл',bins:'Добавить контейнер',products:'Добавить изделие'};
 async function activateCard(id){setBusy(true);setError('');try{await req('/api/qc/cards/'+id+'/activate',{method:'POST'});await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
 return <div className="layout"><aside className="side"><div className="brand"><b className="mark">M</b><span><strong>MIC 2.0</strong><small>PRODUCTION CONTROL</small></span></div><div className="navTitle">РАБОЧЕЕ ПРОСТРАНСТВО</div>{visibleNav.map(([id,ic,label])=><button key={id} className={'nav '+(page===id?'selected':'')} onClick={()=>{setError('');setPage(id)}}><i>{ic}</i>{label}</button>)}<div className="sideFoot">MIC 2.0 · Производственная система<br/>Все данные сохраняются в базе предприятия</div></aside><main><header><div><div className="eyebrow">MIC / WORKSPACE</div><h1>{TITLES[page]}</h1></div><div className="profile"><span className="avatar">{(employee?.full_name||'A').slice(0,1)}</span><span><b>{employee?.full_name||'Администратор'}</b><small>{employee?.role_title||'Сотрудник'}</small></span><button className="secondary" onClick={logout}>Выйти</button></div></header>
 {error&&<div className="error banner">{error}</div>}{busy?<div className="loading">Загружаем данные…</div>:page==='overview'?(employee?.role_code==='qc_manager'?<QualityOverview metrics={metrics}/>:<><div className="metrics"><Metric title="Активные циклы" value={metrics.active_cycles??'—'} note="Сейчас в производстве"/><Metric title="Активные изделия" value={metrics.active_products??'—'} note="Номенклатура"/><Metric title="Открытые дефекты" value={metrics.open_defects??'—'} note="Требуют решения"/></div><div className="section"><div><h2>Контейнерный парк</h2><p>Распределение оборотной тары</p></div>{allowedPages.includes('bins')&&<button className="secondary" onClick={()=>setPage('bins')}>Открыть контейнеры →</button>}</div><div className="metrics compact"><Metric title="Свободные" value={metrics.bins?.find(x=>x.bin_status==='free')?.count??0} note="Готовы к запуску"/><Metric title="Занятые" value={metrics.bins?.find(x=>x.bin_status==='occupied')?.count??0} note="На производстве"/><Metric title="В архиве" value={metrics.bins?.find(x=>x.bin_status==='archived')?.count??0} note="Не используются"/><Metric title="Система" value="MIC 2.0" note="База данных подключена"/></div><div className="section"><div><h2>Рабочие разделы</h2><p>Основные процессы производства и контроля</p></div></div><div className="tiles">{visibleNav.filter(([id])=>id!=='overview').map(([id,ic,label])=><button className="tile" key={id} onClick={()=>setPage(id)}><i>{ic}</i><b>{label}</b><small>Перейти в раздел →</small></button>)}</div></>):page==='admin'?<AdminPanel data={data} refresh={load} create={()=>openCreate('employee')} toggle={async(id,status)=>{try{await req('/api/admin/accounts/'+id+'/status',{method:'POST',body:JSON.stringify({account_status:status})});await load();}catch(e){setError(e.message);}}}/>:page==='schedule'?<ScheduleTable data={data} refresh={load} roleCode={employee?.role_code} create={(date)=>openCreate(employee?.role_code==='qc_manager'?'shiftPattern':'shift',date)}/>:page==='qc-my-shifts'?<MyShifts data={data} refresh={load}/>:page==='qc-calendar'?<QcShiftCalendar data={data} refresh={load} markAttendance={async(id,status,note,actualTime)=>{await req('/api/qc/my-shifts/'+id+'/attendance',{method:'POST',body:JSON.stringify({attendance_status:status,attendance_note:note,actual_time:actualTime})});await load();}}/>:page==='qc-production'?<QcProduction data={data} refresh={load} startFly={(cycle)=>{setForm({cycle_id:String(cycle.cycle_id),sample_quantity:5,defect_quantity:0,inspection_result:'pass',defect_description:'',action_required:false,comment:'',measurements:(cycle.measurement_parameters||[]).map(p=>({parameter_id:p.id,measured_value:'',comment:''}))});setModal('fly');setLookups({cycle});}}/>:page==='qc-fly'?<FlyControlPage data={data} refresh={load} detail={async(id)=>{const r=await req('/api/qc/fly-control/'+id);return r.check;}} create={async()=>{try{const r=await req('/api/qc/production');setForm({cycle_id:'',sample_quantity:5,defect_quantity:0,inspection_result:'pass',defect_description:'',action_required:false,comment:'',measurements:[]});setModal('fly');setLookups({cycles:r.cycles||[]});}catch(e){setError(e.message);}}}/>:page==='qc-defects'?<DefectsTable data={data} decide={async(payload)=>{setBusy(true);setError('');try{await req('/api/qc/defects/'+payload.id+'/decisions',{method:'POST',body:JSON.stringify(payload)});await load();}catch(e){setError(e.message);}finally{setBusy(false);}}}/>:page==='qc-cards'?<CardsTable data={data} refresh={load} create={()=>openCreate('card')} activate={activateCard}/>:page==='qc-history'?<InspectionHistory data={data} refresh={load}/>:<DataTable page={page} data={data} refresh={load} create={openCreate} roleCode={employee?.role_code} output={(id)=>{setForm({cycle_id:id});setModal('output')}} qcInspect={(r)=>{setForm({cycle_id:r.cycle_id,good_quantity:0,defect_quantity:0,measurements:(r.measurement_parameters||[]).map(p=>({parameter_id:p.id,measured_value:'',comment:''}))});setModal('qc')}}/>}
 </main>{modal&&<div className="modalShade" onMouseDown={e=>{if(e.target===e.currentTarget)setModal('')}}><form className="modalCard" onSubmit={submit}><div className="modalHead"><h2>{{bin:'Новый контейнер',product:'Новое изделие и наладка',employee:'Создать учётную запись',cycle:'Открыть производственный цикл',output:'Внести выпуск деталей',qc:'Результат контроля ОТК',shift:'Назначить смену',shiftPattern:'Сформировать график ОТК',card:'Новая карта измерений'}[modal]}</h2><button type="button" className="secondary" onClick={()=>setModal('')}>Закрыть</button></div>

 {modal==='fly'&&<><SelectField label="Производственный цикл" value={form.cycle_id} set={v=>{const cycle=(lookups.cycles||[]).find(x=>String(x.cycle_id)===v)||lookups.cycle;setLookups(prev=>({...prev,cycle}));set('cycle_id',v);set('measurements',(cycle?.measurement_parameters||[]).map(p=>({parameter_id:p.id,measured_value:'',comment:''})));}} options={(lookups.cycles|| (lookups.cycle?[lookups.cycle]:[])).map(c=>[String(c.cycle_id),`Контейнер №${c.bin_id} · ${c.product_name_snapshot} · цикл ${c.cycle_no}`])}/><Field label="Размер выборки, деталей" type="number" min="1" value={form.sample_quantity} set={v=>set('sample_quantity',v)} required/><SelectField label="Результат" value={form.inspection_result} set={v=>set('inspection_result',v)} options={ [['pass','Соответствует'],['observation','Замечание / наблюдение'],['fail','Обнаружено несоответствие']]}/>{form.inspection_result==='fail'&&<><Field label="Количество дефектных в выборке" type="number" min="1" value={form.defect_quantity} set={v=>set('defect_quantity',v)} required/><Field label="Описание несоответствия" value={form.defect_description} set={v=>set('defect_description',v)} required/></>}<label className="checkField"><input type="checkbox" checked={!!form.action_required} onChange={e=>set('action_required',e.target.checked)}/> Требуется внимание начальника ОТК</label><Field label="Комментарий" value={form.comment} set={v=>set('comment',v)}/>{(lookups.cycle?.measurement_parameters||[]).map((p,i)=><div className="parameterEditor" key={p.id}><b>{p.parameter_name} · норма {p.nominal_value||'—'} {p.unit||''} · допуск {p.tolerance_text||'—'}</b><Field label="Измеренное значение" value={form.measurements?.find(m=>m.parameter_id===p.id)?.measured_value} set={v=>setFlyMeasurement(p.id,v)}/></div>)}</>}
 {modal==='product'&&<><Field label="Код изделия" value={form.product_code} set={v=>set('product_code',v)} required/><Field label="Наименование" value={form.product_name} set={v=>set('product_name',v)} required/><Field label="Описание" value={form.description} set={v=>set('description',v)}/><Field label="Норма деталей в коробке" type="number" value={form.box_quantity_norm} set={v=>set('box_quantity_norm',v)} required/><Field label="Код наладки" value={form.setup_code} set={v=>set('setup_code',v)} required/><Field label="Название наладки" value={form.setup_name} set={v=>set('setup_name',v)} required/></>}
 {modal==='employee'&&<><Field label="ФИО" value={form.full_name} set={v=>set('full_name',v)} required/><Field label="Должность" value={form.job_title} set={v=>set('job_title',v)} required/><SelectField label="Подразделение" value={form.department} set={v=>set('department',v)} options={[['production','Производство'],['qc','ОТК'],['management','Управление'],['administration','Администрация']]}/><SelectField label="Роль" value={form.role_code} set={v=>set('role_code',v)} options={ROLES}/><Field label="Логин" value={form.login} set={v=>set('login',v)} required/><Field label="Временный пароль (от 10 символов)" type="password" value={form.password} set={v=>set('password',v)} required/></>}
 {modal==='shiftPattern'&&<><SelectField label="Контролёр ОТК" value={form.employee_id} set={v=>set('employee_id',v)} options={lookups.candidates?.map(x=>[String(x.id),x.full_name])||[]}/><SelectField label="Рабочий график" value={form.pattern_code} set={v=>set('pattern_code',v)} options={ [['3x3','3 рабочих / 3 выходных'],['5x2','Понедельник–пятница, выходные — суббота и воскресенье']] }/><Field label="Дата начала графика" type="date" value={form.start_date} set={v=>set('start_date',v)} required/><div className="formHint">MIC автоматически сформирует дневные смены на 12 месяцев вперёд. Прошедшие смены и отметки явки сохраняются. При замене графика пересчитываются только будущие запланированные смены.</div><Field label="Примечание" value={form.notes} set={v=>set('notes',v)}/></>}
 {modal==='shift'&&<><SelectField label="Сотрудник" value={form.employee_id} set={v=>{const person=(lookups.candidates||[]).find(x=>String(x.id)===v);setForm(f=>({...f,employee_id:v,shift_code:person?.role_code==='qc_controller'?'day':(f.shift_code||'day')}));}} options={lookups.candidates?.map(x=>[String(x.id),x.full_name+' — '+(x.role_code==='qc_controller'?'Контролёр ОТК':'Оператор ЧПУ')])||[]}/><Field label="Дата смены" type="date" value={form.shift_date} set={v=>set('shift_date',v)} required/>{employee?.role_code==='qc_manager'?null:lookups.candidates?.find(x=>String(x.id)===String(form.employee_id))?.role_code==='qc_controller'?<div className="formField"><span>График</span><strong>Дневной — автоматически</strong></div>:form.employee_id?<SelectField label="Смена оператора" value={form.shift_code} set={v=>set('shift_code',v)} options={[['day','Дневная'],['night','Ночная']]}/>:null}<Field label="Примечание" value={form.notes} set={v=>set('notes',v)}/></>}
 {modal==='cycle'&&<><SelectField label="Свободный контейнер" value={form.bin_id} set={v=>set('bin_id',v)} options={lookups.bins?.map(x=>[String(x.id),'Контейнер №'+String(x.id).padStart(3,'0')])||[]}/><SelectField label="Изделие" value={form.product_id} set={v=>set('product_id',v)} options={lookups.products?.map(x=>[String(x.id),x.product_code+' — '+x.product_name])||[]}/><SelectField label="Наладка" value={form.setup_id} set={v=>set('setup_id',v)} options={lookups.products?.filter(x=>String(x.id)===String(form.product_id)).flatMap(x=>x.setups.map(s=>[String(s.id),s.setup_code+' — '+s.setup_name]))||[]}/><SelectField label="Оператор ЧПУ" value={form.operator_id} set={v=>set('operator_id',v)} options={lookups.operators?.map(x=>[String(x.id),x.full_name])||[]}/>{!lookups.bins?.length&&<p>Нет свободных контейнеров. Сначала добавьте контейнер.</p>}{!lookups.products?.length&&<p>Нет активных изделий. Сначала добавьте изделие.</p>}{!lookups.operators?.length&&<p>Нет активных операторов ЧПУ. Сначала создайте учётную запись оператора.</p>}</>}
 {modal==='card'&&<><SelectField label="Наладка" value={form.setup_id} set={v=>set('setup_id',v)} options={lookups.products?.flatMap(p=>p.setups.map(x=>[String(x.id),p.product_code+' / '+x.setup_code+' — '+x.setup_name]))||[]}/><div className="section"><div><h3>Параметры измерения</h3><p>Укажите название, номинал, допуск и единицу</p></div><button type="button" className="secondary" onClick={addCardParameter}>Добавить параметр</button></div>{(form.parameters||[]).map((p,i)=><div className="parameterEditor" key={i}><b>Параметр {i+1}</b><Field label="Наименование" value={p.parameter_name} set={v=>setCardParameter(i,'parameter_name',v)} required/><Field label="Номинальное значение" value={p.nominal_value} set={v=>setCardParameter(i,'nominal_value',v)}/><Field label="Допуск / диапазон" value={p.tolerance_text} set={v=>setCardParameter(i,'tolerance_text',v)}/><Field label="Единица" value={p.unit} set={v=>setCardParameter(i,'unit',v)}/><Field label="Инструкция" value={p.instruction} set={v=>setCardParameter(i,'instruction',v)}/>{i>0&&<button type="button" className="secondary smallButton" onClick={()=>setForm(f=>({...f,parameters:f.parameters.filter((_,n)=>n!==i)}))}>Удалить параметр</button>}</div>)}</>}
 {modal==='output'&&<><Field label="Количество произведённых деталей" type="number" value={form.quantity} set={v=>set('quantity',v)} required/><Field label="Примечание" value={form.note} set={v=>set('note',v)}/></>}
 {modal==='qc'&&<><p>Цикл №{form.cycle_id}. Укажите результат контроля для доступного количества.</p><Field label="Годные детали" type="number" min={0} value={form.good_quantity} set={v=>set('good_quantity',v)} required/><Field label="Дефектные детали" type="number" min={0} value={form.defect_quantity} set={v=>set('defect_quantity',v)} required/><Field label="Описание дефекта (если есть)" value={form.defect_description} set={v=>set('defect_description',v)}/><Field label="Комментарий ОТК" value={form.comment} set={v=>set('comment',v)}/>{(form.measurements||[]).length>0&&<><h3>Замеры по карте измерений</h3>{form.measurements.map((m,i)=><div className="parameterEditor" key={m.parameter_id}><b>Параметр {i+1}</b><Field label="Фактическое значение" value={m.measured_value} set={v=>setMeasurement(i,'measured_value',v)} required/><Field label="Комментарий к замеру" value={m.comment} set={v=>setMeasurement(i,'comment',v)}/></div>)}</>}</>}
 {error&&<div className="error modalError">{error}</div>}<div className="modalActions"><button type="button" className="secondary" onClick={()=>setModal('')}>Отмена</button><button className="primary" disabled={busy}>{busy?'Сохраняем…':'Сохранить'}</button></div></form></div>}</div>;
}
function CardsTable({data,refresh,create,activate}){const cards=data.cards||[];return <><div className="section"><div><h2>Карты измерений</h2><p>Версии привязаны к наладкам; в цикле фиксируется карта, действовавшая на момент запуска</p></div><div className="tableActions"><button className="secondary" onClick={refresh}>Обновить ↻</button><button className="primary" onClick={create}>Создать карту</button></div></div>{cards.length?cards.map(c=><article className="cardRecord" key={c.id}><div className="section"><div><b>{c.parameters.map(p=>p.parameter_name).join(' · ')}</b><p>Наладка #{c.setup_id} · версия {c.version_no} · {c.parameters.length} параметров</p></div><span className={'status '+c.review_status}>{({draft:'Черновик',checked:'Проверена',active:'Действует',archived:'Архив'}[c.review_status]||c.review_status)}</span></div><div className="parameterList">{c.parameters.map(p=><span key={p.id}>{p.parameter_name}: {p.nominal_value||'—'} {p.tolerance_text?`(${p.tolerance_text})`:''} {p.unit||''}</span>)}</div>{c.review_status==='draft'&&<button className="primary" onClick={()=>activate(c.id)}>Проверить и активировать</button>}</article>):<div className="empty">Карты измерений ещё не созданы. Создайте первую карту для наладки.</div>}</>;}
function InspectionHistory({data,refresh}){const rows=data.inspections||[];return <><div className="section"><div><h2>История проверок</h2><p>Журнал завершённых и сохранённых проверок ОТК</p></div><button className="secondary" onClick={refresh}>Обновить ↻</button></div><div className="tableWrap">{rows.length?<table><thead><tr><th>Дата</th><th>Контейнер</th><th>Изделие</th><th>Контролёр</th><th>Тип</th><th>Карта</th><th>Замеры</th><th>Комментарий</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{new Date(r.started_at).toLocaleString('ru-RU')}</td><td>№ {r.bin_id}</td><td>{r.product_name_snapshot}</td><td>{r.controller_name}</td><td>{({first_piece:'Первая деталь',scheduled_round:'Плановая',defect_recheck:'Повторная',rework_acceptance:'После доработки',isolator_return:'Возврат из изолятора',fly_control:'Летучий контроль'}[r.inspection_type]||r.inspection_type)}</td><td>{r.card_version?`v${r.card_version}`:'Без карты'}</td><td>{r.measured_parameters}</td><td>{r.comment||'—'}</td></tr>)}</tbody></table>:<div className="empty">Проверок пока нет.</div>}</div></>;}
function QualityOverview({metrics}){return <div className="metrics"><Metric title="Открытые дефекты" value={metrics.open_defects??0} note="Ожидают решения начальника ОТК"/><Metric title="Проверки сегодня" value={metrics.inspections_today??0} note="Завершённые проверки"/><Metric title="Детали ожидают ОТК" value={metrics.pending_qc??0} note="Доступны для контроля"/></div>;}
function AdminPanel({data,refresh,create,toggle}){const rows=data.employees||[];return <><div className="section"><div><h2>Полное управление учётными записями</h2><p>Все сотрудники, роли и состояние доступа к MIC 2.0</p></div><div className="tableActions"><button className="secondary" onClick={refresh}>Обновить ↻</button><button className="primary" onClick={create}>Создать учётную запись</button></div></div><div className="tableWrap">{rows.length?<table><thead><tr><th>Сотрудник</th><th>Подразделение</th><th>Должность</th><th>Роль</th><th>Логин</th><th>Доступ</th><th>Действие</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.full_name}<small>№{r.employee_no||r.id}</small></td><td>{r.department}</td><td>{r.job_title}</td><td>{r.role_title}</td><td>{r.login}</td><td><span className={'status '+(r.account_status==='active'?'active':'draft')}>{r.account_status==='active'?'Активен':'Заблокирован'}</span></td><td><button className="secondary smallButton" onClick={()=>toggle(r.id,r.account_status==='active'?'blocked':'active')}>{r.account_status==='active'?'Заблокировать':'Восстановить'}</button></td></tr>)}</tbody></table>:<div className="empty">Учётные записи не найдены.</div>}</div></>}
function ScheduleTable({data,refresh,create,roleCode}) {
 const [cursor,setCursor]=useState(()=>new Date()),[view,setView]=useState('month');
 const [editShift,setEditShift]=useState(null),[editStart,setEditStart]=useState(''),[editEnd,setEditEnd]=useState(''),[editError,setEditError]=useState(''),[savingTimes,setSavingTimes]=useState(false);
 const rows=data.shifts||[],patterns=data.patterns||[];
 const fmt=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
 const first=new Date(cursor.getFullYear(),cursor.getMonth(),1);
 const mondayOffset=(first.getDay()+6)%7;
 const monthStart=new Date(first);monthStart.setDate(first.getDate()-mondayOffset);
 const weekStart=new Date(cursor);weekStart.setDate(cursor.getDate()-(cursor.getDay()+6)%7);
 const days=Array.from({length:view==='month'?42:7},(_,i)=>{const d=new Date(view==='month'?monthStart:weekStart);d.setDate(d.getDate()+i);return d;});
 const monthName=cursor.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
 const dayNames=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
 const visible=rows.filter(r=>roleCode!=='qc_manager'||r.role_code==='qc_controller').filter(r=>roleCode!=='production_manager'||r.role_code==='cnc_operator');
 const today=fmt(new Date());
 const offNamesForDate=key=>patterns.filter(p=>{const start=String(p.start_date).slice(0,10),end=String(p.end_date).slice(0,10);if(key<start||key>=end)return false;if(p.pattern_code==='5x2'){const day=new Date(key+'T00:00:00Z').getUTCDay();return day===0||day===6;}const offset=Math.round((Date.parse(key+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000);return offset%6>=3;}).map(p=>p.full_name);
 const move=n=>setCursor(d=>new Date(d.getFullYear(),d.getMonth()+(view==='month'?n:0),d.getDate()+(view==='week'?n*7:0)));
 const statusLabel={pending:'Запланирована',present:'На смене',absent:'Отсутствует',replaced:'Замена',left_early:'Ушел раньше'};
 const openTimeEditor=r=>{setEditShift(r);setEditStart(r.actual_start_time?String(r.actual_start_time).slice(0,5):'');setEditEnd(r.actual_end_time?String(r.actual_end_time).slice(0,5):'');setEditError('');};
 async function saveTimes(e){e.preventDefault();setSavingTimes(true);setEditError('');try{await req('/api/production/shifts/'+editShift.id+'/attendance-times',{method:'PATCH',body:JSON.stringify({actual_start_time:editStart||null,actual_end_time:editEnd||null})});setEditShift(null);await refresh();}catch(err){setEditError(err.message);}finally{setSavingTimes(false);}}
 return <><div className="section calendarTop"><div><h2>Календарь смен</h2><p>{roleCode==='qc_manager'?'Графики контролёров ОТК: дневные смены по циклу 3/3 или рабочей неделе 5/2. Планирование на 12 месяцев.':'Назначения по датам и сотрудникам. ЧПУ — дневные и ночные смены.'}</p></div><div className="tableActions"><button className="secondary" onClick={()=>setCursor(new Date())}>Сегодня</button><button className="secondary" onClick={()=>move(-1)}>←</button><button className="secondary" onClick={()=>move(1)}>→</button><button className="secondary" onClick={refresh}>Обновить ↻</button><button className="primary" onClick={()=>create(fmt(cursor))}>{roleCode==='qc_manager'?'Сформировать график':'+ Назначить смену'}</button></div></div>
 <div className="calendarToolbar"><strong>{monthName}</strong><div className="calendarViews"><button className={view==='month'?'active':''} onClick={()=>setView('month')}>Месяц</button><button className={view==='week'?'active':''} onClick={()=>setView('week')}>Неделя</button></div></div>
 <div className="calendarGrid">{dayNames.map(d=><div className="calendarWeekday" key={d}>{d}</div>)}{days.map(d=>{const key=fmt(d),events=visible.filter(r=>String(r.shift_date).slice(0,10)===key),weekend=d.getDay()===0||d.getDay()===6;return <div className={'calendarDay '+(d.getMonth()!==cursor.getMonth()&&view==='month'?'outside ':'')+(key===today?' today':'')+(roleCode==='qc_manager'&&weekend?' weekend':'')} key={key}>{roleCode==='qc_manager'?<div className="calendarDate">{d.getDate()}</div>:<button className="calendarDate" onClick={()=>create(key)} title="Назначить смену на эту дату">{d.getDate()} <span>+</span></button>}{roleCode==='qc_manager'?offNamesForDate(key).map(name=><small className="calendarOff" key={name}>Выходной · {name}</small>):null}{events.map(ev=><div className={'shiftEvent '+(ev.role_code==='qc_controller'?'qcShift':ev.shift_code==='night'?'nightShift':'dayShift')} key={ev.id}><b>{ev.shift_code==='night'?'Ночь':'День'}</b><span>{ev.full_name}</span><small>{statusLabel[ev.attendance_status]||ev.attendance_status}</small>{ev.role_code==='qc_controller'&&<>{ev.actual_start_time&&<small>Приход {String(ev.actual_start_time).slice(0,5)}</small>}{ev.actual_end_time&&<small>Уход {String(ev.actual_end_time).slice(0,5)}</small>}</>}</div>)}</div>;})}</div>
 {roleCode==='qc_manager'?<><div className="calendarLegend"><span><i className="legendQc"/>Рабочий день ОТК</span><span>Выходные — без назначений</span></div><div className="patternList"><div><b>Активные графики</b><small>Каждый контролёр может иметь один действующий график</small></div>{patterns.length?patterns.map(p=><div className="patternItem" key={p.id}><strong>{p.full_name}</strong><span>{p.pattern_code==='3x3'?'3 рабочих / 3 выходных':'Пн–Пт / Сб–Вс выходные'}</span><small>С {new Date(String(p.start_date).slice(0,10)+'T00:00:00').toLocaleDateString('ru-RU')} по {new Date(new Date(String(p.end_date).slice(0,10)+'T00:00:00').getTime()-86400000).toLocaleDateString('ru-RU')}</small></div>):<p className="empty">Графики ещё не сформированы.</p>}</div></>:<div className="calendarLegend"><span><i className="legendDay"/>Дневная смена</span><span><i className="legendNight"/>Ночная смена ЧПУ</span><span><i className="legendQc"/>Контролёр ОТК</span></div>}
 <div className="section"><div><h2>Список назначений</h2><p>{visible.length} записей в доступном периоде</p></div></div>
 <div className="tableWrap">{visible.length?<table><thead><tr><th>Дата</th><th>Сотрудник</th><th>Должность</th><th>Смена</th><th>Явка / время</th><th>Примечание</th></tr></thead><tbody>{visible.slice().sort((x,y)=>String(x.shift_date).localeCompare(String(y.shift_date))).map(r=><tr key={r.id}><td>{new Date(String(r.shift_date).slice(0,10)+'T00:00:00').toLocaleDateString('ru-RU')}</td><td>{r.full_name}</td><td>{r.role_code==='qc_controller'?'Контролёр ОТК':'Оператор ЧПУ'}</td><td>{r.shift_code==='night'?'Ночная':'Дневная'}</td><td><span className="status">{statusLabel[r.attendance_status]||r.attendance_status}</span>{r.role_code==='qc_controller'&&<>{r.actual_start_time&&<small>Приход: {String(r.actual_start_time).slice(0,5)}</small>}{r.actual_end_time&&<small>Уход: {String(r.actual_end_time).slice(0,5)}</small>}</>}</td><td>{r.notes||'—'}{r.role_code==='qc_controller'&&r.attendance_note&&<small>{r.attendance_note}</small>}</td></tr>)}</tbody></table>:<div className="empty">{roleCode==='qc_manager'?'На выбранный период нет назначенных рабочих дней. Нажмите «Сформировать график», чтобы автоматически заполнить календарь на 12 месяцев.':'На выбранный период смены ещё не назначены. Нажмите «+» в ячейке даты, чтобы добавить сотрудника.'}</div>}</div></>;
 {editShift&&<div className="modalShade" onMouseDown={e=>{if(e.target===e.currentTarget)setEditShift(null);}}><form className="modalCard" onSubmit={saveTimes}><div className="modalHead"><h2>Корректировка времени явки</h2><button type="button" className="secondary" onClick={()=>setEditShift(null)}>Закрыть</button></div><p><b>{editShift.full_name}</b> · {new Date(String(editShift.shift_date).slice(0,10)+'T00:00:00').toLocaleDateString('ru-RU')}</p><label className="formField">Фактическое время прихода<input type="time" value={editStart} onChange={e=>setEditStart(e.target.value)}/></label><label className="formField">Фактическое время ухода<input type="time" value={editEnd} onChange={e=>setEditEnd(e.target.value)}/></label><small>Пустое поле означает, что время не зафиксировано.</small>{editError&&<div className="error">{editError}</div>}<div className="modalFoot"><button type="button" className="secondary" onClick={()=>setEditShift(null)}>Отмена</button><button className="primary" disabled={savingTimes}>{savingTimes?'Сохраняем…':'Сохранить время'}</button></div></form></div>}

}
function Field({label,value,set,type='text',required=false,min}){return <label className="formField">{label}<input type={type} value={value??''} onChange={e=>set(e.target.value)} required={required} min={min??(type==='number'?1:undefined)}/></label>}
function SelectField({label,value,set,options=[]}){return <label className="formField">{label}<select value={value??''} onChange={e=>set(e.target.value)} required><option value="">Выберите…</option>{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>}


function QcShiftCalendar({data,refresh,markAttendance}){
 const [cursor,setCursor]=useState(()=>new Date()),[view,setView]=useState('month');
 const [selected,setSelected]=useState(null),[status,setStatus]=useState('present'),[note,setNote]=useState(''),[actualTime,setActualTime]=useState(''),[saving,setSaving]=useState(false),[localError,setLocalError]=useState('');
 const rows=data.shifts||[],patterns=data.patterns||[];
 const fmt=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
 const first=new Date(cursor.getFullYear(),cursor.getMonth(),1),offset=(first.getDay()+6)%7;
 const monthStart=new Date(first);monthStart.setDate(first.getDate()-offset);
 const weekStart=new Date(cursor);weekStart.setDate(cursor.getDate()-(cursor.getDay()+6)%7);
 const days=Array.from({length:view==='month'?42:7},(_,i)=>{const d=new Date(view==='month'?monthStart:weekStart);d.setDate(d.getDate()+i);return d;});
 const today=fmt(new Date()),monthName=cursor.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
 const dayNames=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
 const move=n=>setCursor(d=>new Date(d.getFullYear(),d.getMonth()+(view==='month'?n:0),d.getDate()+(view==='week'?n*7:0)));
 const statusLabel={pending:'Запланирована',present:'На смене',absent:'Не вышел',replaced:'Замена',left_early:'Ушел раньше'};
 const openAttendance=ev=>{setSelected(ev);const next=ev.attendance_status==='pending'?'present':ev.attendance_status;setStatus(next);setNote(ev.attendance_note||'');setActualTime((next==='left_early'?ev.actual_end_time:ev.actual_start_time)||new Date().toTimeString().slice(0,5));setLocalError('');};
 async function saveAttendance(e){e.preventDefault();setSaving(true);setLocalError('');try{await markAttendance(selected.id,status,note,actualTime);setSelected(null);}catch(err){setLocalError(err.message);}finally{setSaving(false);}}
 const offNamesForDate=key=>patterns.filter(p=>{const start=String(p.start_date).slice(0,10),end=String(p.end_date).slice(0,10);if(key<start||key>=end)return false;if(p.pattern_code==='5x2'){const day=new Date(key+'T00:00:00Z').getUTCDay();return day===0||day===6;}const n=Math.round((Date.parse(key+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000);return n%6>=3;}).map(p=>p.full_name);
 return <><div className="section calendarTop"><div><h2>Календарь смен ОТК</h2><p>Общий график всех контролёров. Просмотр без редактирования; свои смены можно отметить</p></div><div className="tableActions"><button className="secondary" onClick={()=>setCursor(new Date())}>Сегодня</button><button className="secondary" onClick={()=>move(-1)}>←</button><button className="secondary" onClick={()=>move(1)}>→</button><button className="secondary" onClick={refresh}>Обновить ↻</button></div></div>
 <div className="calendarToolbar"><strong>{monthName}</strong><div className="calendarViews"><button className={view==='month'?'active':''} onClick={()=>setView('month')}>Месяц</button><button className={view==='week'?'active':''} onClick={()=>setView('week')}>Неделя</button></div></div>
 <div className="calendarGrid">{dayNames.map(d=><div className="calendarWeekday" key={d}>{d}</div>)}{days.map(d=>{const key=fmt(d),events=rows.filter(r=>String(r.shift_date).slice(0,10)===key),weekend=d.getDay()===0||d.getDay()===6;return <div className={'calendarDay '+(d.getMonth()!==cursor.getMonth()&&view==='month'?'outside ':'')+(key===today?' today':'')+(weekend?' weekend':'')} key={key}><div className="calendarDate">{d.getDate()}</div>{offNamesForDate(key).map(name=><small className="calendarOff" key={name}>Выходной · {name}</small>)}{events.map(ev=><div className={'shiftEvent '+(ev.is_own?'qcShift':'dayShift')} key={ev.id}><b>{ev.full_name}</b><span>День</span><small>{statusLabel[ev.attendance_status]||ev.attendance_status}</small>{ev.actual_start_time&&<small>Приход {String(ev.actual_start_time).slice(0,5)}</small>}{ev.actual_end_time&&<small>Уход {String(ev.actual_end_time).slice(0,5)}</small>}{ev.is_own&&key<=today&&<button type="button" className="smallButton secondary attendanceOpen" onClick={()=>openAttendance(ev)}>Отметить</button>}</div>)}</div>;})}</div>
 <div className="calendarLegend"><span><i className="legendQc"/>Ваша смена</span><span><i className="legendDay"/>Смены коллег</span><span>Суббота и воскресенье — выходные по графику 5/2</span></div>
 <div className="section"><div><h2>Смены команды ОТК</h2><p>{rows.length} назначений в доступном периоде. Редактирование графика доступно только начальнику ОТК</p></div></div>
 <div className="tableWrap">{rows.length?<table><thead><tr><th>Дата</th><th>Контролёр</th><th>Смена</th><th>Явка</th><th>Примечание</th></tr></thead><tbody>{rows.slice().sort((a,b)=>String(a.shift_date).localeCompare(String(b.shift_date))).map(r=><tr key={r.id}><td>{new Date(String(r.shift_date).slice(0,10)+'T00:00:00').toLocaleDateString('ru-RU')}</td><td>{r.full_name}{r.is_own&&<small>Вы</small>}</td><td>Дневная</td><td><span className="status">{statusLabel[r.attendance_status]||r.attendance_status}</span>{r.actual_start_time&&<small>Приход: {String(r.actual_start_time).slice(0,5)}</small>}{r.actual_end_time&&<small>Уход: {String(r.actual_end_time).slice(0,5)}</small>}{r.is_own&&String(r.shift_date).slice(0,10)<=today&&<button className="secondary smallButton" onClick={()=>openAttendance(r)}>Изменить отметку</button>}</td><td>{r.notes||'—'}{r.is_own&&r.attendance_note&&<small>Отметка: {r.attendance_note}</small>}</td></tr>)}</tbody></table>:<div className="empty">В календаре пока нет смен. Начальник ОТК должен сформировать график сотрудников.</div>}</div>
 {selected&&<div className="modalShade" onMouseDown={e=>{if(e.target===e.currentTarget)setSelected(null);}}><form className="modalCard" onSubmit={saveAttendance}><div className="modalHead"><h2>Отметка о смене</h2><button type="button" className="secondary" onClick={()=>setSelected(null)}>Закрыть</button></div><p><b>{selected.full_name}</b> · {new Date(String(selected.shift_date).slice(0,10)+'T00:00:00').toLocaleDateString('ru-RU')}</p><label className="formField">Фактическая явка<select value={status} onChange={e=>{setStatus(e.target.value);setActualTime(e.target.value==='left_early'?(selected.actual_end_time||new Date().toTimeString().slice(0,5)):(selected.actual_start_time||new Date().toTimeString().slice(0,5)));}}><option value="present">Вышел на смену</option><option value="left_early">Ушел раньше</option><option value="absent">Не вышел</option></select></label>{(status==='present'||status==='left_early')&&<label className="formField">{status==='present'?'Фактическое время прихода':'Фактическое время ухода'}<input type="time" value={actualTime} onChange={e=>setActualTime(e.target.value)} required/></label>}{status!=='present'&&<label className="formField">Комментарий / причина<textarea value={note} onChange={e=>setNote(e.target.value)} rows="3" maxLength="500" placeholder={status==='left_early'?'Укажите причину раннего ухода':'Причина отсутствия (необязательно)'}/></label>}{status==='left_early'&&!note.trim()&&<small className="error">Для раннего ухода нужно указать причину</small>}{localError&&<div className="error">{localError}</div>}<div className="modalFoot"><button type="button" className="secondary" onClick={()=>setSelected(null)}>Отмена</button><button className="primary" disabled={saving||((status==='present'||status==='left_early')&&!actualTime)||(status==='left_early'&&!note.trim())}>{saving?'Сохраняем…':'Сохранить отметку'}</button></div></form></div>}
 </>;
}

function MyShifts({data,refresh}){const rows=data.shifts||[];return <><div className="section"><div><h2>Мой график</h2><p>Назначенные смены за последние 30 дней и на 12 месяцев вперёд</p></div><button className="secondary" onClick={refresh}>Обновить ↻</button></div><div className="tableWrap">{rows.length?<table><thead><tr><th>Дата</th><th>Смена</th><th>Время</th><th>Явка</th><th>Примечание</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{new Date(String(r.shift_date).slice(0,10)+'T00:00:00').toLocaleDateString('ru-RU')}</td><td>{{day:'Дневная',night:'Ночная',evening:'Вечерняя'}[r.shift_code]||r.shift_code}</td><td>{r.starts_at?new Date(r.starts_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'—'} – {r.ends_at?new Date(r.ends_at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'—'}</td><td><span className="status">{({pending:'Ожидается',present:'На смене',absent:'Отсутствие',replaced:'Замена'}[r.attendance_status]||r.attendance_status)}</span></td><td>{r.notes||'—'}</td></tr>)}</tbody></table>:<div className="empty">Смены пока не назначены. Когда начальник ОТК добавит вас в расписание, они появятся здесь.</div>}</div></>;}
function QcProduction({data,refresh,startFly}){const rows=data.cycles||[];return <><div className="section"><div><h2>Активные производственные циклы</h2><p>Текущая загрузка производства и состояние деталей по каждому контейнеру</p></div><button className="secondary" onClick={refresh}>Обновить ↻</button></div><div className="tableWrap">{rows.length?<table><thead><tr><th>Контейнер / цикл</th><th>Изделие</th><th>Оператор</th><th>Выпущено</th><th>Ожидает ОТК</th><th>Принято</th><th>Изоляция / доработка</th><th>Действие</th></tr></thead><tbody>{rows.map(r=><tr key={r.cycle_id}><td>№{String(r.bin_id).padStart(3,'0')} / {r.cycle_no}</td><td>{r.product_code_snapshot}<br/>{r.product_name_snapshot}<small>{r.setup_code_snapshot}</small></td><td>{r.operator_name}</td><td>{r.output_quantity}</td><td><b>{r.pending_qc}</b></td><td>{r.good_quantity}</td><td>{r.isolator_quantity} / {r.rework_quantity}</td><td><button className="secondary smallButton" onClick={()=>startFly(r)}>Летучий контроль</button></td></tr>)}</tbody></table>:<div className="empty">Сейчас нет активных производственных циклов.</div>}</div></>;}

function FlyControlPage({data,refresh,create,detail}){
 const rows=data.checks||[];
 const [selected,setSelected]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState('');
 async function open(id){setLoading(true);setError('');try{setSelected(await detail(id));}catch(e){setError(e.message);}finally{setLoading(false);}}
 return <><div className="section"><div><h2>Летучий контроль</h2><p>Выборочные проверки непосредственно во время производства. Они не списывают и не перемещают количество деталей.</p></div><div className="tableActions"><button className="secondary" onClick={refresh}>Обновить ↻</button><button className="primary" onClick={create}>Провести проверку</button></div></div>
 {error&&<div className="error banner">{error}</div>}
 <div className="tableWrap">{rows.length?<table><thead><tr><th>Дата</th><th>Контейнер</th><th>Изделие</th><th>Контролёр</th><th>Выборка</th><th>Результат</th><th>Дефектные</th><th>Замеры</th><th>Действие</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{new Date(r.created_at).toLocaleString('ru-RU')}</td><td>№{r.bin_id} / {r.cycle_no}</td><td>{r.product_name_snapshot}<small>{r.setup_code_snapshot}</small></td><td>{r.controller_name}</td><td>{r.sample_quantity}</td><td><span className={'status '+(r.inspection_result==='pass'?'active':r.inspection_result==='fail'?'draft':'')}>{({pass:'Соответствует',fail:'Несоответствие',observation:'Замечание'}[r.inspection_result])}</span></td><td>{r.defect_quantity}{r.defect_description&&<small>{r.defect_description}</small>}</td><td>{r.measured_parameters}</td><td><button className="secondary smallButton" onClick={()=>open(r.id)}>Подробнее</button>{r.action_required&&<small>Внимание начальника ОТК</small>}</td></tr>)}</tbody></table>:<div className="empty">Летучих проверок пока нет. Выберите активный цикл и проведите первую проверку.</div>}</div>
 {selected&&<div className="modalShade" onMouseDown={e=>{if(e.target===e.currentTarget)setSelected(null);}}><div className="modalCard"><div className="modalHead"><h2>Летучий контроль · №{selected.bin_id} / цикл {selected.cycle_no}</h2><button className="secondary" onClick={()=>setSelected(null)}>Закрыть</button></div><p>{selected.product_code_snapshot} · {selected.product_name_snapshot} · {selected.setup_code_snapshot}</p><div className="metrics compact"><Metric title="Выборка" value={selected.sample_quantity} note="Проверено деталей"/><Metric title="Дефектные" value={selected.defect_quantity} note="В выборке"/><Metric title="Карта" value={selected.card_version?'v'+selected.card_version:'—'} note="Версия карты измерений"/></div><p>Результат: <b>{({pass:'Соответствует',fail:'Несоответствие',observation:'Замечание'}[selected.inspection_result])}</b></p>{selected.defect_description&&<p>Описание: {selected.defect_description}</p>}{selected.action_required&&<p className="error">Требует внимания начальника ОТК</p>}<h3>Измерения</h3>{selected.measurements?.length?<div className="tableWrap"><table><thead><tr><th>Параметр</th><th>Норма</th><th>Допуск</th><th>Факт</th><th>Комментарий</th></tr></thead><tbody>{selected.measurements.map((m,i)=><tr key={i}><td>{m.parameter_name}</td><td>{m.nominal_value||'—'} {m.unit||''}</td><td>{m.tolerance_text||'—'}</td><td>{m.measured_value}</td><td>{m.comment||'—'}</td></tr>)}</tbody></table></div>:<div className="empty">Измерения не вводились.</div>}{selected.comment&&<p>Комментарий: {selected.comment}</p>}</div></div>}
 {loading&&<div className="loading">Загружаем проверку…</div>}
 </>;
}

function DefectsTable({data,decide}){
 const [values,setValues]=useState({}),defects=data.defects||[];
 const labels={with_good_product:'Принять как годные',isolator:'В изолятор',rework:'На доработку',scrap:'В брак'};
 return <><div className="section"><div><h2>Дефекты, ожидающие решения</h2><p>{defects.length} открытых записей. Количество можно распределять частями.</p></div></div>
 <div className="tableWrap">{defects.length?<table><thead><tr><th>Контейнер / цикл</th><th>Изделие и наладка</th><th>Дефект</th><th>Подтверждено</th><th>Осталось</th><th>Решение</th></tr></thead><tbody>{defects.map(d=><tr key={d.id}><td>№{d.bin_id} / {d.cycle_no}</td><td>{d.product_code_snapshot} · {d.product_name_snapshot}<br/><small>{d.setup_code_snapshot}</small></td><td>{d.defect_description}<br/><small>{d.controller_name} · {new Date(d.confirmed_at).toLocaleString()}</small></td><td>{d.confirmed_quantity}</td><td><b>{d.undecided_quantity}</b></td><td>{d.undecided_quantity>0?<form className="decisionForm" onSubmit={e=>{e.preventDefault();const v=values[d.id]||{};decide({id:d.id,decision_type:v.type||'isolator',quantity:Number(v.quantity||d.undecided_quantity),note:v.note||''});}}><select value={values[d.id]?.type||'isolator'} onChange={e=>setValues(p=>({...p,[d.id]:{...p[d.id],type:e.target.value}}))}>{Object.entries(labels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><input type="number" min="1" max={d.undecided_quantity} value={values[d.id]?.quantity??d.undecided_quantity} onChange={e=>setValues(p=>({...p,[d.id]:{...p[d.id],quantity:e.target.value}}))}/><input placeholder="Комментарий" value={values[d.id]?.note||''} onChange={e=>setValues(p=>({...p,[d.id]:{...p[d.id],note:e.target.value}}))}/><button className="primary smallButton" type="submit">Зафиксировать</button></form>:<span>Решено</span>}</td></tr>)}</tbody></table>:<div className="empty">Открытых дефектов нет</div>}</div></>;
}
function Metric({title,value,note}){return <article className="metric"><small>{title}</small><strong>{value}</strong><span>{note}</span></article>}
function DataTable({page,data,refresh,create,roleCode,output,qcInspect}){const rows=data[page]||[];const cols={qc:[['Контейнер',r=>'№ '+String(r.bin_id).padStart(3,'0')],['Изделие',r=>r.product_name_snapshot],['Оператор',r=>r.responsible_name],['Ожидает контроля',r=>r.available_quantity],['Дефект зарезервирован',r=>r.reserved_defect_quantity]],cycles:[['Контейнер',r=>'№ '+String(r.bin_id).padStart(3,'0')],['Изделие',r=>r.product_name_snapshot],['Наладка',r=>r.setup_code_snapshot],['Ответственный',r=>r.responsible_name],['Количество',r=>r.physical_quantity],['Ожидает ОТК',r=>r.pending_qc],['Статус',r=>r.cycle_status==='active'?'Активен':'Завершён']],bins:[['Контейнер',r=>'№ '+String(r.id).padStart(3,'0')],['Состояние',r=>({free:'Свободен',occupied:'Занят',archived:'В архиве'}[r.bin_status]||r.bin_status)],['Изделие',r=>r.product_name_snapshot||'—'],['Оператор',r=>r.responsible_name||'—'],['Количество',r=>r.physical_quantity??0]],products:[['Код',r=>r.product_code],['Наименование',r=>r.product_name],['Норма коробки',r=>r.box_quantity_norm],['Наладки',r=>(r.setups||[]).map(s=>s.setup_code).join(', ')||'—']],employees:[['Сотрудник',r=>r.full_name],['Подразделение',r=>r.department],['Должность',r=>r.job_title],['Роль',r=>r.role_title],['Статус',r=>r.account_status==='active'?'Активен':'Заблокирован']]};return <><div className="section"><div><h2>{TITLES[page]}</h2><p>{rows.length} записей</p></div><div className="tableActions"><button className="secondary" onClick={refresh}>Обновить ↻</button>{page==='bins'&&<button className="primary" onClick={()=>create('bin')}>Добавить контейнер</button>}{page==='cycles'&&['production_manager','administrator'].includes(roleCode)&&<button className="primary" onClick={()=>create('cycle')}>Открыть цикл</button>}{page==='products'&&['production_manager','administrator'].includes(roleCode)&&<button className="primary" onClick={()=>create('product')}>Добавить изделие</button>}</div></div><div className="tableWrap">{rows.length?<table><thead><tr>{cols[page].map(c=><th key={c[0]}>{c[0]}</th>)}{(page==='cycles'||page==='qc')&&<th>Действия</th>}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.id||i}>{cols[page].map(([label,fn])=><td key={label}>{fn(r)}</td>)}{page==='cycles'&&<td>{r.cycle_status==='active'&&['cnc_operator','administrator','production_manager'].includes(roleCode)?<button className="secondary smallButton" onClick={()=>output(r.id)}>Внести выпуск</button>:'—'}</td>}{page==='qc'&&<td><button className="secondary smallButton" onClick={()=>qcInspect(r)}>Внести результат ОТК</button></td>}</tr>)}</tbody></table>:<div className="empty">В этом разделе пока нет записей</div>}</div></>}
